import sys

def solve():
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        x, y = map(int, sys.stdin.readline().split())
        adj[x].append(y)
        adj[y].append(x)

    def ask(u, v):
        sys.stdout.write(f"? {u} {v}\n")
        sys.stdout.flush()
        res = sys.stdin.readline()
        if not res or res.strip() == "-1":
            return None
        return int(res.strip())

    leaves = []
    for i in range(1, n + 1):
        if len(adj[i]) == 1:
            leaves.append(i)

    if n == 2:
        print("! 1")
        return

    candidate = leaves[0]
    for i in range(1, len(leaves)):
        l = leaves[i]
        res = ask(candidate, l)
        if res is None:
            return
        if res != candidate:
            candidate = res

    print(f"! {candidate}")

if __name__ == "__main__":
    solve()
